@push('scripts')<script>(function(){function decode(v){const b=Uint8Array.from(atob(v),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(b));}document.querySelectorAll('.js-dept-edit').forEach(b=>b.addEventListener('click',()=>{const r=decode(b.dataset.record);[['dept-edit-id','id'],['dept-edit-faculty','faculty'],['dept-edit-code','code'],['dept-edit-no','no'],['dept-edit-title','title'],['dept-edit-status','status']].forEach(([i,k])=>document.getElementById(i).value=r[k]??'');}));document.querySelectorAll('.js-entity-delete').forEach(b=>b.addEventListener('click',()=>{const prefix=b.dataset.action.includes('department')?'dept':'entity';document.getElementById(prefix+'-delete-id').value=b.dataset.id;document.getElementById(prefix+'-delete-title').textContent=b.dataset.title;document.getElementById(prefix+'-delete-form').action=b.dataset.action;}));})();</script>@endpush
